import { useState } from "react";

function useCart() {
  const [items, setItems] = useState<string[]>([]);
  const add = (id: string) => setItems([...items, id]);
  return { count: items.length, add };
}

export function CartBadge() {
  const { count } = useCart(); // its own items array, always empty
  return <span>Cart ({count})</span>;
}

export function AddToCart({ productId }: { productId: string }) {
  const { add } = useCart(); // a second, unrelated items array
  return <button onClick={() => add(productId)}>Add to cart</button>;
}

import { createContext, useContext, useState, type ReactNode } from "react";

type Cart = { count: number; add: (id: string) => void };
const CartContext = createContext<Cart | null>(null);

export function CartProvider({ children }: { children: ReactNode }) {
  // The only items array, owned by a parent of every cart component
  const [items, setItems] = useState<string[]>([]);
  const add = (id: string) => setItems([...items, id]);
  return (
    <CartContext value={{ count: items.length, add }}>{children}</CartContext>
  );
}

// Same name, same return shape: CartBadge and AddToCart don't change
export function useCart(): Cart {
  const cart = useContext(CartContext);
  if (!cart) throw new Error("useCart must be used inside <CartProvider>");
  return cart;
}
